// Involute spur gear outline as a closed, star-shaped polygon about the axis.
// Used as the cutter when rails or mates are generated by rolling (5.3).
export type V2=[number,number];
export type InvoluteOptions={module:number;teeth:number;pressureAngle?:number;backlash?:number;shift?:number;samples?:number};
const inv=(a:number)=>Math.tan(a)-a;

export function involuteOutline({module:m,teeth:z,pressureAngle=20,backlash=0,shift=0,samples=12}:InvoluteOptions):V2[]{
 if(!(m>0)||!Number.isInteger(z)||z<3)throw Error('Evolventenrad: Modul und Zähnezahl prüfen.');
 const alpha=pressureAngle*Math.PI/180,rp=m*z/2,rb=rp*Math.cos(alpha),ra=rp+m*(1+shift),rf=rp-m*(1.25-shift);
 // Tooth thickness at the pitch circle, reduced by half the backlash on this gear.
 const thickness=Math.PI*m/2+2*shift*m*Math.tan(alpha)-backlash/2,half=(r:number)=>{const phi=Math.acos(Math.min(1,rb/r));return thickness/(2*rp)+inv(alpha)-inv(phi);};
 const start=Math.max(rb,rf),flank:{r:number;b:number}[]=[];
 for(let i=0;i<=samples;i++){const r=start+(ra-start)*i/samples;flank.push({r,b:half(r)});}
 const tipHalf=Math.max(0,half(ra)),pitch=2*Math.PI/z,points:V2[]=[];
 const at=(r:number,t:number):V2=>[r*Math.cos(t),r*Math.sin(t)];
 for(let k=0;k<z;k++){const c=k*pitch;
  // Root from the previous gap centre to the flank foot, rising flank, tip, falling flank, root to the next gap centre.
  const foot=flank[0].b;points.push(at(rf,c-pitch/2));if(rf<start)points.push(at(rf,c-foot));
  for(const p of flank)points.push(at(p.r,c-p.b));
  const tipSteps=Math.max(1,Math.ceil(samples/3));for(let i=1;i<tipSteps;i++)points.push(at(ra,c-tipHalf+2*tipHalf*i/tipSteps));
  for(const p of [...flank].reverse())points.push(at(p.r,c+p.b));
  if(rf<start)points.push(at(rf,c+foot));
 }
 return points;
}
export const pitchRadius=(m:number,z:number)=>m*z/2;
